<!DOCTYPE html>
<html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cài đặt — Fieldcraft</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=Oswald:wght@500;600&display=swap" rel="stylesheet"><style>:root{--bg:#f4f7f1;--card:#fff;--ink:#07110d;--line:#dce5d9;--muted:#6f7e74;--lime:#caff39;--danger:#ca4129}body.dark{--bg:#0a1711;--card:#112118;--ink:#edf5ed;--line:#2d4435;--muted:#a7b7aa}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:500 13px Manrope,sans-serif}.wrap{max-width:1080px;margin:auto;padding:30px 20px 70px}.brand{color:var(--ink);text-decoration:none;font:600 28px Oswald,sans-serif}.brand i{display:inline-block;width:20px;height:20px;margin-right:7px;background:var(--lime);border-radius:2px 10px 2px 10px;transform:rotate(-20deg)}h1{font:600 42px/.95 Oswald,sans-serif;text-transform:uppercase;margin:35px 0 23px}.shell{display:grid;grid-template-columns:225px 1fr;gap:18px}.tabs{background:var(--card);border:1px solid var(--line);border-radius:9px;padding:10px;height:max-content;position:sticky;top:18px}.tabs button{display:flex;width:100%;border:0;border-radius:5px;padding:11px;background:transparent;color:var(--muted);font:700 11px Manrope;text-align:left;cursor:pointer}.tabs button.active,.tabs button:hover{background:var(--ink);color:var(--card)}.pane{display:none}.pane.active{display:block;animation:in .18s ease}.panel{background:var(--card);border:1px solid var(--line);border-radius:9px;padding:23px;margin-bottom:14px}.panel h2{font:600 25px Oswald,sans-serif;text-transform:uppercase;margin:0 0 4px}.muted{color:var(--muted);font-size:11px;line-height:1.6}.field{display:block;font-size:10px;font-weight:800;margin-top:15px}.field input,.field select{box-sizing:border-box;width:100%;padding:11px;margin-top:6px;border:1px solid var(--line);background:transparent;color:var(--ink);border-radius:4px;outline:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.btn{border:0;border-radius:4px;padding:11px 14px;background:var(--lime);color:#07110d;font:800 11px Manrope;cursor:pointer;margin-top:20px}.btn.gray{background:var(--ink);color:var(--card)}.btn.danger{background:#ffece8;color:var(--danger)}.notice{padding:11px 13px;background:#e7f5db;color:#3c6e28;border-radius:5px;font-size:11px;margin-bottom:15px}.avatar{width:82px;height:82px;border-radius:50%;object-fit:cover;background:#dcebd5;display:grid;place-items:center;font:600 31px Oswald}.avatar-row{display:flex;align-items:center;gap:17px}.switch{display:flex;align-items:center;justify-content:space-between;padding:13px 0;border-bottom:1px solid var(--line)}.switch:last-child{border:0}.switch input{width:40px;height:22px;accent-color:#5e9324}.address{border:1px solid var(--line);padding:13px;border-radius:5px;margin-top:9px}.address b{font-size:11px}.badge{font:500 9px Manrope;padding:4px 6px;border-radius:3px;background:#e6f5da;color:#3e762b;margin-left:6px}.progress{height:9px;background:#e4ece0;border-radius:9px;margin:13px 0}.progress i{display:block;height:100%;background:var(--lime);border-radius:9px}.social{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:15px}.social button{border:1px solid var(--line);padding:12px;background:transparent;color:var(--ink);border-radius:4px;font-weight:700;font-size:10px}.device{display:flex;justify-content:space-between;padding:13px 0;border-bottom:1px solid var(--line)}.device:last-child{border:0}.guest{max-width:510px}.language{position:absolute;right:20px;top:25px;border:1px solid var(--line);background:var(--card);color:var(--ink);padding:7px;border-radius:4px;font-size:10px}@keyframes in{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}@media(max-width:720px){.shell{grid-template-columns:1fr}.tabs{position:static;display:flex;overflow:auto;padding:7px}.tabs button{min-width:max-content}.grid{grid-template-columns:1fr}.social{grid-template-columns:1fr}.language{position:static;float:right;margin-top:-55px}}
