</main><script>const applyTheme=t=>{const dark=t==='dark'||(t==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.body.classList.toggle('dark',dark);localStorage.setItem('fieldcraft-theme',t)};const userTheme='{{ $user?->theme ?? 'system' }}';applyTheme(localStorage.getItem('fieldcraft-theme')||userTheme);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab],.pane').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.tab).classList.add('active')});document.getElementById('profileTheme')?.addEventListener('change',e=>applyTheme(e.target.value));document.getElementById('darkGuest')?.addEventListener('change',e=>applyTheme(e.target.checked?'dark':'light'));document.getElementById('systemGuest')?.addEventListener('change',e=>applyTheme(e.target.checked?'system':'light'));document.getElementById('locale').value='{{ $user?->locale ?? 'vi' }}';document.getElementById('locale').onchange=e=>localStorage.setItem('fieldcraft-locale',e.target.value);</script></body></html>
